message.content:
{"diagnosis": "Loopback RX latched recv_buf_data as 0xe0 instead of expected 0xa5, causing uart data mismatch trap. Both bit-period checks at lines 90 and 97 use (cfg_divider >> 4) instead of cfg_divider, making the receiver sample ~16x too fast. With divider 64 this samples inside start/data transitions and shifts wrong bits into recv_pattern.", "patch_diff": "diff --git a/picosoc/simpleuart.v b/picosoc/simpleuart.v
--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -89,14 +89,14 @@
 				10: begin
-					if (recv_divcnt > (cfg_divider >> 4)) begin
+					if (recv_divcnt > cfg_divider) begin
 						recv_buf_data <= recv_pattern;
 						recv_buf_valid <= 1;
 						recv_state <= 0;
 					end
 				end
 				default: begin
-					if (recv_divcnt > (cfg_divider >> 4)) begin
+					if (recv_divcnt > cfg_divider) begin
 						recv_pattern <= {ser_rx, recv_pattern[7:1]};
 						recv_state <= recv_state + 1;
 						recv_divcnt <= 0;
 					end
 				end
", "expected": "tohost PASS, TRAP gone, uart loopback got 0xa5 want 0xa5"}

